import{_ as t,o as s,c as e,ag as l}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"CalcTool 计算工具坐标系","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/CalcTool.md","filePath":"3. 指令/5. 设置指令/CalcTool.md","lastUpdated":1778862643000}'),n={name:"3. 指令/5. 设置指令/CalcTool.md"};function o(i,a,r,d,h,p){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="calctool-计算工具坐标系" tabindex="-1">CalcTool 计算工具坐标系 <a class="header-anchor" href="#calctool-计算工具坐标系" aria-label="Permalink to &quot;CalcTool 计算工具坐标系&quot;">​</a></h1><p>该指令用于<strong>通过&quot;四点法&quot;自动计算机器人的工具坐标系（TCP）参数</strong>。当末端工具（如焊枪尖端或针头）的具体几何尺寸未知时，通过从四个不同的姿态将工具尖端对准同一个参考基准点，系统即可精确推算出工具相对于法兰中心的偏移量。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>CalcTool(P1, P2, P3, P4, Tool) CalcTool(点1, 点2, 点3, 点4, 工具变量)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P1, P2, P3, P4：标定点</td><td>CPOS（笛卡尔位置）</td><td>记录下机器人末端工具尖端指向<strong>同一空间固定点</strong>时的四个不同姿态的位置数据。</td><td>为了提高计算精度，这四个点位的姿态差异应尽可能大。</td></tr><tr><td>Tool：工具参数（Tool Param）</td><td>TOOL 变量</td><td>存储计算结果的容器。指令执行成功后，计算出的偏移值（X, Y, Z）将写入此变量。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>四点法的核心在于&quot;变姿态而不变位置&quot;。系统通过四个不同的法兰盘位置坐标，利用球形拟合算法计算出工具尖端到法兰中心的唯一矢量。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 假设 P1-P4 已经示教完成，均对准了工作台上的同一个针尖</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CalcTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, P2, P3, P4, TOOL1)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 计算完成后切换使用该工具</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(TOOL1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>执行结果：</strong></p><p>系统根据四组坐标计算出 TCP 偏移，并将结果保存至 <strong>TOOL1</strong>。此后，机器人可以绕着该工具尖端进行旋转，而尖端在空间中保持不动。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>新工具上线</strong>：安装了新的焊枪、吸盘或切削刀具后，快速获取其精确的 TCP 坐标。</li><li><strong>碰撞后重新校准</strong>：如果末端工具发生轻微形变，无需重新示教所有点位，只需重新执行一次四点标定即可。</li><li><strong>动态更换工具</strong>：在生产过程中，如果由于工艺需求需要更换不同长度的针头，可通过该指令在程序中实现半自动校准。</li></ul>`,18)])])}const b=t(n,[["render",o]]);export{u as __pageData,b as default};
